ee:variables.ee:set-variable:
%dw 2.0
output application/json skipNullOn = "everywhere"
fun getFilterParams(filters) =
  ((((filters default "") splitBy ";") filter ((item) -> !isEmpty(trim(item))) reduce ((item, acc = {
}) -> do {
	var parts = trim(item) match /^([^:]+):(.*)$/
	---
	if ( isEmpty(parts) ) acc
      else
        acc ++ {
		(upper(trim(parts[1]))): trim(parts[2])
	}
})) default {
}) distinctBy ((value, key) -> key)
---
getFilterParams(attributes.queryParams.FILTERS)

%dw 2.0
output application/java
var dateRange = ["START_DATE", "END_DATE"]
var rules = [{
	route: "QUERY_BILL_PDF",
	required: ["INVOICE_NUMBER", "BILLING_ACCOUNT"],
	optional: []
},
  {
	route: "QUERY_INVOICE_PDF",
	required: ["TRANSACTION_ID", "INVOICE_TYPE"],
	optional: ["COMMENTS"]
},
  {
	route: "QUERY_BILL_HISTORY",
	required: ["CONNECTION_NUMBER"],
	optional: dateRange
},
  {
	route: "QUERY_BILL_HISTORY",
	required: ["CONNECTION_NUMBER", "BILLING_ACCOUNT"],
	optional: dateRange
},
  {
	route: "QUERY_BILL_HISTORY",
	required: ["CONNECTION_NUMBER", "INVOICE_NUMBER"],
	optional: dateRange
},
  {
	route: "QUERY_BILL_HISTORY",
	required: ["CUSTOMER_ID_TYPE", "CUSTOMER_ID"],
	optional: dateRange
}]

fun matches(rule, keys) = 
 isEmpty(rule.required -- keys) and isEmpty(keys -- (rule.required ++ rule.optional))

var filters = vars.filters
var keys = keysOf(filters filterObject((value) -> !isEmpty(value))) map ($ as String)
var matched = (rules filter((value) -> matches(value, keys)))[0]
---
matched.route default "INVALID"

ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
    "status": "400",
    "code": "HTTP:BAD_REQUEST",
    "message": error.description,
    "messageServer": error.failingComponent default "VALIDATION:INVALID_BOOLEAN",
    "cause": [
        {
            "origin": "customer-papi-services-v2",
            "message": error.description
        }
    ]
}

%dw 2.0
output application/json
---
{
    "status": "400",
    "code": "HTTP:BAD_REQUEST",
    "message": error.description,
    "messageServer": error.failingComponent default "VALIDATION:MULTIPLE",
    "cause": [
        {
            "origin": "customer-papi-services-v2",
            "message": error.description
        }
    ]
}

%dw 2.0
output application/json
---
{
    "status": "400",
    "code": "BILLING_HISTORY:INVALID_PARAMS",
    "message": "(CONNECTION_NUMBER; BILLING_ACCOUNT) and (CUSTOMER_ID_TYPE; CUSTOMER_ID) combination cant be empty at the same time.",
    "messageServer": error.failingComponent default "BILLING_HISTORY:INVALID_PARAMS",
    "cause": [
        {
            "origin": "customer-papi-services-v2",
            "message": error.description,
        }
    ]
}
